quests[8886] = { id = 8886, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Piraten der Grimmschuppen!", description = "Wie gut, dass Ihr hier seid, {class}! Diese schleimigen Grimmschuppenmurlocs haben meine Fracht gestohlen! Als wenn es nicht schon schlimm genug wäre, dass die Getriebenen mir meine letzten magischen Güter geraubt haben - und jetzt das! Was ist nur aus diesem Land geworden?\n\nKönnt Ihr mir meine Fracht wiederbeschaffen? Ich erwarte zwar nicht, dass Ihr alles zurückerlangt, bin aber für jedes Stück dankbar. Es waren die Grimmschuppenmurlocs in den Hütten im Westen, südlich des Ankerplatzes am Goldenen Strand. Ich bin mir ganz sicher!", sourceObjective = "Erlangt 6 Stücke von Kapitänin Kelisendras Fracht wieder und bringt sie zu Kapitänin Kelisendra beim befestigten Lager direkt östlich des Ankerplatzes der Sonnensegel im Immersangwald zurück.", progress = "Ich bin dankbar für die Unterstützung von jemandem wie Euch, {name}. Es stimmt mich fast schon wieder fröhlich. Allerdings erinnert es mich auch daran, was diese Monster meinem Schiff angetan haben und was mit Quel'Thalas geschieht.\n\nHabt Ihr es geschafft, Teile meiner Fracht wiederzuerlangen?", completion = "Ihr habt es geschafft! Ihr habt mich vor dem Ruin bewahrt und die scheußlichen Kreaturen meine Vergeltung spüren lassen!\n\nWenn ich es jetzt noch schaffe, dass mir diese hübschen Waldläufer mit meiner Fracht helfen, dann komme ich endlich weg von hier! Ich muss noch einmal zurückkehren, wenn Velendris die Schiffswerft zurückerobert hat.\n\nHier, nehmt diese Münze. Ich kann Euch leider nicht mehr geben, aber ich hoffe, es entlohnt Eure Mühen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8887] = { id = 8887, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapitänin Kelisendras verlorene Seekarten", description = "Interessant... was Ihr hier gefunden habt, ist eine wasserdichte Lederhülse, die ein paar Seiten Pergamentpapier enthält. Nach den Kennzeichnungen zu urteilen, handelt es sich eindeutig um Seekarten. Jede dieser Karten trägt das Siegel von Kapitänin Kelisendra.\n\nIhr habt sicher schon von einem kleinen, befestigten Lager östlich des nahegelegenen Ankerplatzes der Sonnensegel gehört. Vielleicht findet Ihr die Kapitänin ja dort?", sourceObjective = "Bringt Kapitänin Kelisendras verlorene Seekarten zu Kapitänin Kelisendra beim befestigten Lager direkt östlich des Ankerplatzes der Sonnensegel im Immersangwald zurück.", progress = "Hallo, {class}, Euer Anblick ist ein gutes Zeichen. Ich weiß, es ist verrückt, dass ich überhaupt hier bin, wo der Ankerplatz doch von den Getriebenen überfallen wurde. Velendris und seine Waldläufer haben geschworen mich zu beschützen, unter der Bedingung, dass ich von hier verschwinde, sobald ich meine Fracht wiedererlangt habe.\n\nWas habt Ihr da... das kommt mir so bekannt vor?", completion = "Oh, Ihr herzensguter, herzensguter {class}! Ich hatte ja keine Ahnung, dass diese widerlichen Grimmschuppenmurlocs auch noch meine Seekarten entwendet hatten! Ohne diese Karten hätte ich niemals wieder in See stechen können, sobald wir den Ankerplatz zurückerobert und das Schiff repariert haben.\n\nIch bin Euch zutiefst dankbar! Hier, nehmt diese Münze als Zeichen meiner Anerkennung.", sourceObjectiveStatus = "unverified-source-field" }
quests[8888] = { id = 8888, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Lehrling des Magisters", description = "{class}, hört Euch mein Anliegen an. Auf Grund von Dingen, die ich jetzt nicht weiter erklären kann, habe ich beschlossen, meine nahegelegene Schule zu schließen. Vor ein paar Tagen habe ich eine meiner Schülerinnen, Lehrling Loralthalis, mit diesem Auftrag dorthin geschickt. Seitdem habe ich nichts mehr von ihr gehört.\n\nWerdet Ihr zum Nachtschimmerturm gehen und nachsehen, ob alles mit ihr in Ordnung ist? Ihr werdet den Turm finden, indem Ihr dem Pfad, der von der Zuflucht der Weltenwanderer aus nach Norden führt, folgt und dann bei der Weggabelung rechts abbiegt.", sourceObjective = "Sprecht mit Lehrling Loralthalis nahe des Nachtschimmerturms im Immersangwald.", completion = "Der Magister sorgt sich um mein Wohlergehen? Wie süß von ihm; ich wünschte, er hätte ein derartiges Interesse etwas früher gezeigt, als wir noch im Turm waren.\n\nNaja, das tut jetzt nichts zur Sache. Hört gut zu, {class}, ich muss Euch um einen Gefallen bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8889] = { id = 8889, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deaktivierung des Turms", description = "Wie Ihr wisst, hat mich Magister Nachtschimmer hierher zurückgeschickt, damit ich die Kraftquellen, die den Turm versorgen, deaktiviere. Es gibt drei davon, sie befinden sich an unterschiedlichen Stellen im Innern des Turms.\n\nUnglücklicherweise scheine ich zu spät zu sein, denn der Nachtschimmerturm wurde von seltsamen, magischen Kreaturen überrannt. Ich habe nicht das benötigte Wissen, um diese Aufgabe zu erfüllen, aber <ein/eine:c> {class} wie Ihr könnte es doch sicherlich ohne größere Probleme?", sourceObjective = "Deaktiviert 3 Kraftquellen des Nachtschimmerturms im Nachtschimmerturm. Bringt anschließend das Deaktivierungsjuwel zu Lehrling Loralthalis im Immersangwald.", progress = "Ich kann es aus dieser Entfernung nicht mit Sicherheit sagen... habt Ihr den Nachtschimmerturm bereits deaktiviert?", completion = "Ich bin Euch für Eure Hilfe dankbar, aber es betrübt mich zu hören, dass einige meiner Lehrlingsfreunde der Abhängigkeit verfallen sind.\n\nJetzt, da die Kraftquellen des Turms deaktiviert wurden, werde ich wohl noch eine Weile hier bleiben. Ich möchte sehen, ob sich die Lage beruhigt, damit ich mich hineinschleichen kann, um ihre Überreste zu bergen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8890] = { id = 8890, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht vom Turm", description = "{name}, ich hätte noch eine letzte Bitte an Euch. Würdet Ihr Magister Nachtschimmer bei der Zuflucht der Weltenwanderer über die Ereignisse berichten, die hier vorgefallen sind? Sagt ihm, dass es mir gut geht, aber betont bitte auch, dass einige Lehrlinge zu Getriebenen geworden sind.\n\nVielen Dank für Eure Hilfe!", sourceObjective = "Kehrt zu Magister Nachtschimmer bei der Zuflucht der Weltenwanderer im Immersangwald zurück.", completion = "Nein! Ich war zu spät. Es ist alles meine Schuld.\n\nMeine Untersuchungen hinsichtlich der Aufbereitung alternativer Magiequellen sind mir außer Kontrolle geraten und ich konnte nichts mehr tun, was dies hätte aufhalten können. Wäre ich nur selbst gegangen... oder hätten sie auf mich gehört und meine Warnungen befolgt!\n\nMeine Hände sind mit Blut befleckt, {class}. Ich danke Euch dennoch, dass Ihr diese armen Seelen meiner ehemaligen Lehrlinge erlöst habt. Es ist ein kleiner Trost zu wissen, dass sie nicht länger in dem Zustand verweilen müssen, an dessen Stelle ein {race} besser tot wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[8891] = { id = 8891, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufgegebene Untersuchungen", description = "Ihr habt ein Buch mit Untersuchungsberichten gefunden, das offenbar von Magister Nachtschimmer zurückgelassen wurde. Ihr überfliegt rasch den Inhalt und stellt mit Entsetzen fest, dass man versucht hat, verderbte magische Ströme zu filtern, was womöglich eine Erklärung für die Ereignisse hier beim Nachtschimmerturm sein könnte. Der Magister möchte dies sicherlich zurück.", sourceObjective = "Bringt Magister Nachtschimmers Tagebuch zu Magister Nachtschimmer bei der Zuflucht der Weltenwanderer im Immersangwald zurück.", progress = "Was ist das? Es kommt mir bekannt vor. Oh nein, dieses Tagebuch... meine Untersuchungen... dies hat all die schrecklichen Ereignisse verursacht.", completion = "Hier ist er also, {name}, der Beweis für mein Verbrechen. Dieses Tagebuch enthält all meine schlecht durchdachten Studien.\n\nIch schenkte den Warnungen keine Beachtung und führte meine Untersuchungen fort, bis es schon fast zu spät war. Als ich endlich meine Fehler einsah, tat ich alles in meiner Macht Stehende. Allerdings sind einige meiner Schüler zu diesem Zeitpunkt bereits zu weit gegangen. Ich evakuierte den Turm, um sie vor der Verderbnis in Schutz zu bringen. Jedoch vergaß ich in meiner Eile, die Kraftquellen zu deaktivieren.\n\nIch werde diese Aufzeichnungen verbrennen, damit sie zukünftig keinen Schaden mehr anrichten können. Ich wollte den Sin'dorei doch nur helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8892] = { id = 8892, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorfall beim Ankerplatz der Sonnensegel", description = "Der Ankerplatz der Sonnensegel wurde von einem Haufen Getriebener überrannt. Sobald wir Verstärkung erhalten, werden wir diesen Verbrechern schon zeigen, wer hier das Sagen hat, {name}.\n\nIn der Zwischenzeit könntet Ihr uns helfen, indem Ihr ihnen etwas Disziplin beibringt. Geht zu ihnen und macht deutlich, dass man mit uns keine Spielchen treibt. Der Ankerplatz der Sonnensegel liegt genau westlich von Morgenluft.", sourceObjective = "Tötet 5 getriebene Rohlinge und 5 getriebene Straßendiebe und erstattet Waldläufer Degolien im Immersangwald Bericht.", completion = "Das wird ihnen zeigen, dass man es sich mit uns besser nicht verscherzt. Gute Arbeit, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[8893] = { id = 8893, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Super-Ei-O-Mat", progress = "Der Super-Ei-O-Mat ist die neueste Erfindung von Curgle Cranklehop. Es ist eine ziemlich beeindruckende Maschine.\n\nDer Super-Ei-O-Mat fängt wild an zu spucken und zu zischen, als Ihr Euch der Steuerkonsole nähert.", completion = "Ihr legt das Hippogryphen-Ei in die Maschine. Es folgen eine Reihe von Pieptönen sowie ein seltsames Rasseln, Rattern und Klicken.\n\nEs scheint, als hätte das Ei-O-Meter Euer Ei gewogen, vermessen und verpackt. Das ist echt ein zügiger Service!" }
quests[8894] = { id = 8894, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sicherung des Grunds", description = "Ich kann Euch sagen, es ist furchtbar! Seltsame Dinge gehen im Turm vor sich, der Magister und seine Lehrlinge sind weggelaufen und wie Ihr wisst, wurde der gesamte Grund von magischen Bestien überrannt! Und wer sagte Wyllithen Bescheid? Niemand, so sieht es aus!\n\n{class}, Ihr müsst mir helfen, hier wieder für Ordnung zu sorgen... ich kann nicht länger über den Grund wachen, solange diese 'Anomalien' hier in blinder Wut herumlaufen!", sourceObjective = "Tötet 6 Manaschlangen und 6 Ätherbestien. Kehrt anschließend zu Grundbewahrer Wyllithen beim Nachtschimmergrund im Immersangwald zurück.", progress = "Habt Ihr Euch darum gekümmert? Ist Euch eine ausreichende Zahl dieser magischen Anomalien zum Opfer gefallen? Was würde ich nur tun, wenn Magister Nachtschimmer zurückkäme und all diese Bestien wären noch hier?", completion = "Nun, ich denke, das dürfte fürs Erste genügen, oder nicht? Danke für die Hilfe, {class}. Ich hoffe nur, dass ich hier alles rechtzeitig absichern kann, bevor der Magister zum Nachtschimmerturm zurückkommt.\n\nNehmt dies bisschen Kleingeld; es ist nicht viel, aber ich habe im Moment nicht mehr. Ihr könnt ruhig noch ein paar Bestien mehr töten, wenn Ihr hier unterwegs seid, das wäre nett von Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[8895] = { id = 8895, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lieferung an das Sanktum des Nordens", description = "Es freut mich, dass Ihr Euch zumindest in gewissen Hinsichten als fähig erweist, {name}. Ich gebe Euch eine weitere Aufgabe, da Ihr so begierig scheint, Euch beweisen zu wollen.\n\nDies ist ein Brief für Leybewahrer Caidanis, der Arkanist, der für die Aufrechterhaltung des Sanktums des Nordens verantwortlich ist. Geht vom Falkenplatz Richtung Südwesten und Ihr werdet ihn finden. Er ist eine sehr wichtige Persönlichkeit, ich hoffe also, dass Ihr ihn nicht mit zu belanglosem Geschwätz belästigt.", sourceObjective = "Überbringt den unbeschrifteten Brief an Leybewahrer Caidanis beim Sanktum des Nordens im Immersangwald.", progress = "Ja, {class}?", completion = "Vielen Dank, {name}. Ich habe diesen Brief bereits erwartet.", sourceObjectiveStatus = "unverified-source-field" }
quests[8896] = { id = 8896, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zwergenspion", description = "Seid Ihr sicher, dass Ihr diese Notizen bei einer Nachtelfe gefunden habt? Das meiste davon wurde in Zwergisch verfasst...\n\nAusgrabungsleiter Ambossel! Er wurde von Eisenschmiede wegen eines diplomatischen Auftrags hierher geschickt. Ich hätte es wissen müssen, sein Interesse an unseren arkanen Sankten war etwas zu groß. {name}, findet den Zwerg im Sanktum des Nordens und kümmert Euch um ihn. Oh, bitte geht diskret dabei vor.", sourceObjective = "Findet und tötet Ausgrabungsleiter Ambossel im Sanktum des Nordens und berichtet anschließend Aeldon Sonnenmal im Immersangwald.", sourceObjectiveStatus = "unverified-source-field" }
quests[8897] = { id = 8897, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Colara", description = "Wenn ich das Tor bewache muss ich ständig an meine geliebte Colara denken. Ich kann sie immer nur für ein paar kurze Stunden sehen, wenn ich Glück habe. Ach, seht mich doch an. Ich erhalte nur einen niederen Offizierssold und jeden Tag könnte ich an die Front abberufen werden.\n\nWürde sie mich dann einfach vergessen? Ich meine, es gibt so viele wohlhabende Männer in der Stadt.\n\nHier, ich habe einige Dinge aufgeschrieben... Nicht viel, aber vielleicht könntet Ihr diese Nachricht meiner Liebsten überbringen. Mein Dank wäre Euch gewiss.", sourceObjective = "Bringt Lieutenant Heldrics sorgfältig verfasste Notiz zu Colara Dean außerhalb der Bank von Stormwind.", progress = "Hallo, Süßer. Kann ich dir irgendwie helfen?", completion = "Oh, ist das nicht süß! Es ist das erste Mal, dass er mir überhaupt etwas schickt. Glaubt Ihr, er meint es ernst?\n\nColara Heldric? Das hat etwas Klangvolles, findet Ihr nicht? Oh, vielleicht bin ich etwas zu voreilig. Vielen Dank!", sourceObjectiveStatus = "unverified-source-field" }
quests[8898] = { id = 8898, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Colara", description = "Als ich geschäftlich mit der Bank in Stormwind zu tun hatte, traf ich ein Mädchen. Sie hat mir auf Anhieb mein Herz gestohlen. Ich kann einfach nicht mehr aufhören, an sie zu denken! Ich würde Ihr gerne diese Nachricht schicken. Ganze Zwölfmal musste ich sie neu schreiben!\n\nJetzt möchte ich sicherstellen, dass sie meinen Brief auch erhält.\n\nVielleicht reist Ihr ja nach Stormwind und könnt mir weiterhelfen?", sourceObjective = "Bringt den zerknitterten Brief zu Colara Dean außerhalb der Bank in Stormwind.", progress = "Hallo, Süßer. Kann ich dir irgendwie helfen?", completion = "Tormek? Oh ja, ich erinnere mich an ihn. Er hatte einen sehr gepflegten Bart und obendrein ein recht ansehnliches Lächeln.\n\nIch kann es kaum fassen, dass er sich noch an mich erinnert!", sourceObjectiveStatus = "unverified-source-field" }
quests[8899] = { id = 8899, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Colara", description = "Wie soll ich Ihre Schönheit nur beschreiben? Tausende Jahre voll der Poesie und mir fehlen die Worte.\n\nDiese Sterblichen verwässern den Geist und am Ende bleiben wir als plappernde Narren zurück.\n\nZu lange habe ich diese Worte immer und immer wieder in mich aufgenommen. Es ist mir unmöglich sie weiter zu verfeinern. Nein, sie muss diese Nachricht noch heute erhalten, oder ein anderer Verehrer wird sie für sich einnehmen.", sourceObjective = "Bringt den makellosen Brief zu Colara Dean außerhalb der Bank von Stormwind.", progress = "Hallo, Süßer. Kann ich dir irgendwie helfen?", completion = "Ich habe noch nie etwas Derartiges erhalten. Wie liebenswert!", sourceObjectiveStatus = "unverified-source-field" }
quests[8900] = { id = 8900, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Elenia", description = "Sie war so traurig. Ich habe es genau gespürt, trotz Ihrer Versuche es zu verbergen. Ich meine, sie wirkte so traurig, versteht Ihr?\n\nDa war diese Verbindung zwischen uns beiden, als ich mit ihr sprach. Niemand hatte mich bisher verstanden, doch sie tat es auf Anhieb.\n\nAls ich es den anderen erzählte, lachten sie nur über mich und so habe ich nie wieder mit ihr gesprochen. Doch ich vermisse sie. Würdet Ihr mir einen Gefallen tun und ihr diesen Brief von mir geben? Ich will sicher sein, dass sie ihn auch erhält.", sourceObjective = "Bringt die leicht zerknitterte Notiz zu Elenia Haydon nahe der Bank in Undercity.", progress = "Oh, und welchen Umständen verdanke ich dieses Vergnügen?", completion = "Man mag es kaum glauben, dass ein Orc derart wortgewandt sein kann. Natürlich hatten wir bisher kaum Chancen, die Orcs im Allgemeinen besser kennenzulernen. Vielen Dank, für das Überbringen dieses Briefs.", sourceObjectiveStatus = "unverified-source-field" }
quests[8901] = { id = 8901, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Elenia", description = "Habt Ihr jemals wahre Liebe erfahren, <junger Herr/junge Dame>? Noch vor kurzem war dies ein Fremdwort für mich, doch dann traf ich dieses junge Mädchen aus Undercity, Elenia. Es ist selten für einen Angehörigen meiner Art, sich mit den anderen Völker einzulassen, ganz besonders mit den Verlassenen.\n\nDoch jetzt sind meine Gedanken Tag und Nacht von ihr erfüllt.\n\nWäre es Euch vielleicht möglich, ihr diesen Brief zu überbringen? Ich möchte, dass sie hierher nach Mulgore kommt. Hoffentlich sagt sie ja.", sourceObjective = "Bringt den sorgfältig verfassten Brief zu Elenia Haydon nahe der Bank in Undercity.", progress = "Oh, und welchen Umständen verdanke ich dieses Vergnügen?", completion = "Welch liebliche Worte Temma für mich fand. Doch, soviel mich seine Verse auch bewegen, ich könnte niemals einen {race} lieben. Wir leben in verschiedenen Welten, unsere Gedanken, unser Äußeres unterscheiden sich zu sehr.\n\nEs ist gut, dass er mir diesen Brief nicht persönlich überbracht hat. Ich könnte es nicht ertragen, sein Herz auf diese Weise zu brechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8902] = { id = 8902, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Liebste Elenia", description = "Zu Lebzeiten hatte ich geschworen, Elenia, meine Jugendliebe, zu meiner Frau zu nehmen. Es ist schon Jahre her, seit ich das letzte Mal an sie denken musste. Doch seit einiger Zeit beherrschen mehr und mehr Gedanken an sie meinen Verstand.\n\nObwohl es eine Ewigkeit her ist, sollte es in unser beider Leben noch etwas Raum für unsere Liebe geben.\n\nIch bin sicher, auch sie wird sich verändert haben. Sei es drum! Wäre es Euch vielleicht möglich, ihr diesen Brief zu überbringen? Ich selbst bin zu nervös, um ihr selbst gegenüberzutreten.", sourceObjective = "Bringt den liebevoll verfassten Brief zu Elenia Haydon nahe der Bank in Undercity.", progress = "Oh, und welchen Umständen verdanke ich dieses Vergnügen?", completion = "Dieser Brief weckt Erinnerungen an ein längst vergangenes Leben, {name}. Elenia Tor. Einst war dies mein Name, wisst Ihr. Eine wundervolle Zeremonie an den Ufern des Sees sollte es werden. Er wollte sich zur Ruhe setzen und gemeinsam wollten wir uns auf einem Bauernhof niederlassen.\n\nEs waren einfache Träume, die wir hatten.\n\nDoch wenn er mich nun sehen könnte, ich glaube kaum, dass er die alte Elenia in mir wiedererkennen würde. Nur kaltes Fleisch und ein totes Herz...", sourceObjectiveStatus = "unverified-source-field" }
quests[8903] = { id = 8903, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Liebschaft", description = "Diese Liebesepidemie hat etwas unnatürliches an sich. Die ganze Situation ist ungebührlich, ja ein Schandfleck, und im schlimmsten Fall eine Bedrohung für die Sicherheit der gesamten Allianz.\n\nDenkt doch nur: Was passiert, wenn sämtliche Wachen von dieser seltsamen Krankheit betroffen werden? Irgendetwas muss geschehen.\n\nGeht zu einer der Wachen hier in Stormwind und seht, ob sie von dieser törichten Epidemie befallen wurde.", sourceObjective = "Besorgt die Karte einer Wache von Stormwind und bringt sie zu Aristan Mottar in Stormwind.", progress = "Waren meine Sorgen berechtigt? Stehen unsere Wachen bereits unter dem Einfluss dieser Liebeskrankheit?", completion = "Es ist also wahr! Das ist unglaublich, wie konnte das nur passieren? Lasst mich einen Moment nachdenken. Es muss doch eine Ursache für all das geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[8904] = { id = 8904, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Liebschaft", description = "Diese Liebesepidemie hat etwas unnatürliches an sich. Die ganze Situation ist abscheulich, und wenn sie erst einmal unsere Verteidigung schwächt, könnte dies zu einer ernsten Bedrohung für uns alle werden.\n\nSchlimm genug, dass bereits ein Großteil unserer Bevölkerung dieses lächerlich säuselnde Verhalten an den Tag legt. Ich denke, selbst unsere Wächter hat es bereits erwischt, dabei sollten sie gegen derartige Einflüsse immun sein.\n\nGeht zu einem der Wächter und seht, ob er von dieser törichten Epidemie befallen wurde.", sourceObjective = "Besorgt eine modrige Karte des Wächters und bringt sie zu Fenstad Argyle in Undercity.", progress = "Waren meine Sorgen berechtigt? Wurden unsere idiotischen Wachen überwältigt?", completion = "Es ist also wahr! Das ist unglaublich, wie konnte das nur passieren? Lasst mich einen Moment nachdenken. Es muss doch eine Ursache für all das geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[8905] = { id = 8905, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein aufrichtiges Angebot", description = "Seid gegrüßt, {class}. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterspring heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.", sourceObjective = "Sammelt 15 Blutproben aus Winterspring und bringt sie zusammen mit 20 Gold und einem Paar Armschienen des Wildherzens zu Deliana in Ironforge.", progress = "Habt Ihr mitgebracht, worum ich Euch gebeten habe, {name}?", completion = "Exzellent! Dann lasst uns den Austausch vornehmen. Es fällt mir nicht leicht, mich von dieser ausgezeichneten Rüstung zu trennen, aber ich fürchte, ich werde sie in nächster Zeit nicht brauchen.\n\nWenn Ihr daran interessiert sein solltet, mehr Arbeit für mich zu erledigen, wäre ich gewillt auch die anderen Teile aufzugeben.", sourceObjectiveStatus = "unverified-source-field" }
quests[8906] = { id = 8906, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein aufrichtiges Angebot", description = "Seid gegrüßt, {class}. Ich habe hier etwas, das Euch interessieren könnte.\n\nEs gleicht der Rüstung, die von Leuten Eures Schlages bevorzugt wird, ist allerdings von weitaus höherer Qualität. Für einen kleinen Gefallen wäre ich bereit, die Armschienen gegen die normalen einzutauschen.\n\nDas Blut der Frostsäbler und Bären, die in Winterspring heimisch sind, hat gewisse Qualitäten, die für mich von Interesse sind. Bringt mir einen guten Vorrat davon und außerdem die Armschienen und etwas Gold. Ich versichere Euch, dass Eure Anstrengungen es wert sein werden.", sourceObjective = "Sammelt 15 Blutproben aus Winterspring und bringt sie zusammen mit 20 Gold und einem Paar Bestienjägerbindungen zu Deliana in Ironforge.", progress = "Habt Ihr mitgebracht, worum ich Euch gebeten habe, {name}?", completion = "Exzellent! Dann lasst uns den Austausch vornehmen. Es fällt mir nicht leicht, mich von dieser ausgezeichneten Rüstung zu trennen, aber ich fürchte, ich werde sie in nächster Zeit nicht brauchen.\n\nWenn Ihr daran interessiert sein solltet, mehr Arbeit für mich zu erledigen, wäre ich gewillt auch die anderen Teile aufzugeben.", sourceObjectiveStatus = "unverified-source-field" }
