quests[8976] = { id = 8976, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[8977] = { id = 8977, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Deliana", description = "War mir eine Freude, mit Euch zusammenzuarbeiten, {name}. Hier ist das fertige Produkt.\n\nIch hoffe, dass es Euch bei Eurem Unterfangen behilflich sein wird. Verbreitet doch bitte die Kunde über meine hervorragenden Dienste, wenn es Euch nichts ausmacht. Ich hätte nichts gegen mehr Kundschaft einzuwenden.", sourceObjective = "Bringt Deliana in Ironforge den extradimensionalen Geisterdetektor.", progress = "Ihr seid zurück?", completion = "Exzellent! Gut gemacht, {name}. Ich bin mir zwar nicht sicher, ob ich der Handwerkskunst des Goblins vertrauen kann, aber mir bleibt keine andere Wahl.", sourceObjectiveStatus = "unverified-source-field" }
quests[8978] = { id = 8978, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Mokvar", description = "War mir eine Freude, mit Euch zusammenzuarbeiten, {name}. Hier ist das fertige Produkt.\n\nIch hoffe, dass es Euch bei Eurem Unterfangen behilflich sein wird. Verbreitet doch bitte die Kunde über meine hervorragenden Dienste, wenn es Euch nichts ausmacht. Ich hätte nichts gegen mehr Kundschaft einzuwenden.", sourceObjective = "Kehrt mit dem extradimensionalen Geisterdetektor zu Mokvar in Orgrimmar zurück.", progress = "Ihr habt den Apparat?", completion = "Ihr seid mit dem Apparat zurückgekehrt! Eure Hingabe beeindruckt mich, {name}. Ausgezeichnete Arbeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[8979] = { id = 8979, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fenstads Verdacht", description = "Ich denke, ich bin dem Grund für das merkwüdige Verhalten auf die Spur gekommen. Habt Ihr den Duft bemerkt, der in letzter Zeit den Gestank der Kanalisation überlagert? Das neue Duftwasser und Parfüm, das gerade so angesagt ist?\n\nUnsere Gedanken werden durch die Wirkung übelster Alchemie vernebelt.\n\nEs gibt nur einen Weg, um ganz sicher zu sein - bringt meinem Freund, Apotheker Zinge, einen Flakon von dem Parfüm und dem Duftwasser. Die Königliche Apothekervereinigung wird die Wahrheit ans Licht bringen.\n\nIch werde Euch für Eure Ausgaben entschädigen, sobald Ihr zurückkommt.", sourceObjective = "Bringt 1 Duftwasserflakon und 1 Parfümflakon zu Apotheker Zinge im Apothekarium von Undercity.", progress = "Womit kann ich Euch zu Diensten sein?", completion = "Wieder eine von Fenstads fixen Ideen, wie ich sehe. Glaubt er denn tatsächlich, die Königliche Apothekervereinigung hätte nichts Besseres zu tun, als seine lächerlichen Ermittlungen zu unterstützen?\n\nNun ja, lassen wir ihm noch einmal seinen Willen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8980] = { id = 8980, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zinges Einschätzung", description = "Das ist in der Tat unerwartet. Es sieht ganz so aus, als ob Fenstad doch noch auf etwas gestoßen sein könnte. Ich habe Spuren von Substanzen gefunden, die in gedankenbeinflussenden Tränken Verwendung finden.\n\nEs ist nicht ungewöhnlich, dass man in Parfüm derartige Spuren auffindet, allerdings sind einige der Zutaten, die ich in den Düften finden konnte, doch recht... merkwürdig. Es handelt sich hierbei um Alchimiekünste, die nur den Erfahrensten vorbehalten sind, so wie die Mitglieder der Königlichen Apothekervereinigung.", sourceObjective = "Kehrt zu Fenstad Argyle außerhalb der Bank von Undercity zurück.", completion = "Ich hatte also Recht. Wir dürfen keine Zeit verlieren. Wir müssen die Quelle dieser verdorbenen Gerüche ausfindig machen.\n\nHier, nehmt dies als Entschädigung für das Duftwasser und Parfüm, das Ihr gekauft habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[8981] = { id = 8981, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschenkübergabe", progress = "Seid Ihr gekommen, um Eurem liebsten Anführer ein Geschenk der Liebe und Verehrung darzubringen?", completion = "Wunderbar! Wunderbar! Ich werde es zu den anderen Geschenken auf den Haufen legen.\n\nIch habe niemals so viele erwartet! \n\nNun, lasst mich mal ein weiteres hinzuzählen..." }
quests[8982] = { id = 8982, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgung der Spur", description = "Wir müssen unbedingt herausfinden, wer der Lieferant ist. Ich habe sie erst kürzlich dabei beobachtet, wie sie einen Parfümflakon in ihrem Bündel verstaute. Sie sagte mir, dass sie es von Norman, dem Gastwirt, erworben hat.", sourceObjective = "Sprecht mit Gastwirt Norman in Undercity.", completion = "Oh ja, ich habe das Parfüm und Duftwasser erst seit kurzem auf Lager. Ich weiß allerdings nicht, wie lange ich es noch in den Regalen haben werde. Alle sind völlig verrückt danach.\n\nMir ist es völlig schleierhaft, was die Leute daran finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[8983] = { id = 8983, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgung der Spur", description = "Ist etwas nicht in Ordnung mit meiner Ware? Nun, ich habe noch nie so viele Leute gesehen, die so sehr nach einer Sache verlangt haben.\n\nIch habe meine Bestände von einer Händlerin namens Mara Rennick. Sie ist neu in der Stadt.\n\nSie erwähnte, dass sie noch einige Waren beim Schneider im Magierviertel abzuliefern hätte.", sourceObjective = "Sprecht mit Mara Rennick bei der Schneiderei im Magierviertel von Undercity.", completion = "Ich befürchte, dass ich meine gesamten Vorräte an Parfüm und Duftwasser an Norman, den Gastwirt, verkauft habe. Möchtet Ihr welche, solltet Ihr mit ihm sprechen - gesetzten Falls er hat noch etwas davon übrig.\n\nLasst Euch aber nicht zu viel Zeit damit. Ich bin mir sicher, dass Ihr das Duftwasser unwiderstehlich finden werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[8984] = { id = 8984, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lüftung des Geheimnisses", description = "Hört mal, die Taten eines abtrünnigen Apothekers sind nicht mein Problem. Sollte er tatsächlich unsere Sache untergraben, werde ich der Erste sein, der Euch die richtige Richtung weist.\n\nSollte er unschuldig sein, wird er nichts zu verbergen haben, oder?\n\nIch habe meine Ware beim Apotheker Staffron Lerent erworben. Er arbeitet im Vorgebirge von Hillsbrad, irgendwo hinter dem Ravenholdt-Anwesen. Ehrlich gesagt, kam er mir etwas komisch vor.", sourceObjective = "Findet Apotheker Staffron Lerent hinter dem Ravenholdt-Anwesen im Vorgebirge von Hillsbrad.", completion = "Ja, ich habe diese Düfte hergestellt. Sie duften wunderbar, nicht war? Unwiderstehlich.\n\nSobald die Krieger von Allianz und Horde gleichermaßen von Gefühlen der Liebe hingerissen sind, werden sie dem Aufstieg des Schattenrates machtlos gegenüber stehen.\n\nSie werden geschwächt und unvorbereitet sein. Da sie um ihre Liebsten besorgt sind, werden sie die Kontrolle verlieren.\n\nDie Lösung war so einfach. Warum bin ich nicht schon eher darauf gekommen? Die Schwäche aller liegt im Herzen. Es gibt nichts, was Ihr tun könntet, um das Unvermeidbare aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8985] = { id = 8985, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, {class}. Jetzt, da wir wissen, wo mein ehemaliger Kamerad zu finden ist, brauchen wir noch ein paar weitere Dinge, die wir in das Räuchergefäß hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nIsalien, unsere Priesterin, wuchs in Starbreeze in Winterspring auf. Ihr müsst mir ein Relikt von Starbreeze von den Frosthagelriesen der Frostwhisperschlucht im Süden von Winterspring bringen, die dafür bekannt sind, von Zeit zu Zeit den Norden unsicher zu machen.", sourceObjective = "Bringt Bodley in der Blackrockspitze ein Relikt von Starbreeze.", progress = "Seid Ihr schon mit dem zurückgekehrt, worum ich Euch gebeten habe, {class}?", completion = "Ihr habt gute Arbeit geleistet, {name}. Ich werde die Essenz des Relikts in das Räuchergefäß geben.\n\nJetzt müsst Ihr Euch nur noch in den Schrein von Eldretharr im Ostflügel von Düsterbruch begeben und mittels des Räuchergefäßes den korrupierten Geist meiner ehemaligen Kameradin, Isalien, beschwören.  Ihre Seele wurden durch den Einfluss des in Lord Valthalaks Amulett enthaltenen Seelenfragments korrupiert und ihr Geist wird keine Ruhe finden, bevor Ihr es an Euch nehmt.\n\nIch hatte übrigens noch etwas Bluttang von Eurem Ausflug zur Insel Alcaz übrig und habe einige Tränke für Euch gebraut. Sucht Euch was aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[8986] = { id = 8986, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, {class}. Jetzt, da wir wissen, wo das letzte Stück des Amuletts zu finden ist, brauchen wir noch ein paar weitere Dinge, die wir in das Räuchergefäß hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nMor Grayhoof, unser bester Druide, hatte viele enge Freunde im Zirkel des Cenarius, von denen einige den Silithiden zum Opfer gefallen sind. Ihr müsst mir einige Druidenüberreste von den Silithiden beschaffen, die den Bau des Regalschwarms im Südosten von Silithus bewohnen.", sourceObjective = "Bringt Bodley im Blackrock einige Druidenüberreste.", progress = "Seid Ihr schon mit dem zurückgekehrt, worum ich Euch gebeten habe, {class}?", completion = "Ihr habt gute Arbeit geleistet, {name}. Ich werde die Essenz der Überreste in das Räuchergefäß geben.\n\nJetzt müsst Ihr Euch nur noch in Kriegsmeister Voones Kammer in Tazz'Alaor in der unteren Blackrockspitze begeben und mittels des Räuchergefäßes den korrupierten Geist meines ehemaligen Kameraden, Mor Grayhoof, beschwören. Er wird nicht ruhen können, bis er von seinem Stück des Amuletts befreit wird.\n\nIch hatte übrigens noch etwas Bluttang von Eurem Ausflug zur Insel Alcaz übrig und habe einige Tränke für Euch gebraut. Sucht Euch was aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[8987] = { id = 8987, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, {class}. Jetzt, da wir wissen, wo das letzte Stück des Amuletts zu finden ist, brauchen wir noch ein paar weitere Dinge, die wir in das Räuchergefäß hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nDie Geschwister, Jarien und Sothos, glaubten fest an die Lehren des Scharlachroten Kreuzzugs. Sie strebten danach, Ritter dieser abscheulichen Organisation zu werden. Geht zu Tyrs Hand, in den östlichen Pestländern, und beschafft mir ein gleißendes Schwert des Zeloten von den dortigen Prätorianern.", sourceObjective = "Bringt Bodley im Blackrock ein gleißendes Schwert des Zeloten.", progress = "Seid Ihr schon mit dem zurückgekehrt, worum ich Euch gebeten habe, {class}?", completion = "Gute Arbeit, {name}. Ich werde die Essenz des Schwertes in das Räuchergefäß geben.\n\nJetzt müsst Ihr Euch nur noch zum Purpurthron in der scharlachroten Bastion in Stratholme begeben und das Räuchergefäß benutzen, um die Geister meiner ehemaligen Verbündeten, Jarien und Sothos, zu beschwören. Ihre Seelen wurden durch den Einfluss des in Lord Valthalaks Amulett enthaltenen Seelenfragments sicherlich noch weiterhin korrupiert.\n\nIch hatte übrigens noch etwas Bluttang von Eurem Ausflug zur Insel Alcaz übrig und habe einige Tränke für Euch gebraut. Sucht Euch was aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[8988] = { id = 8988, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Komponenten von großer Wichtigkeit", description = "Hört mir gut zu, {class}. Jetzt, da wir wissen, wo das letzte Stück des Amuletts zu finden ist, brauchen wir noch ein paar weitere Dinge, die wir in das Räuchergefäß hineingeben müssen. Wir brauchen einen Fokus, der stark genug ist um den Geist meines verstorbenen Kameraden herbeizurufen.\n\nKormok, ein Ogernekromant, der unsererm Bund angehörte, liebte es die Seelen der verbannten Toten von der Fegefeuer-Insel, nahe der Südküste der Vorgebirge von Hillsbrad, herbeizurufen. Geht dorthin und beschafft mir etwas Seelenasche der Verbannten von ihren Überresten.", sourceObjective = "Bringt Bodley im Blackrock etwas Seelenasche der Verbannten.", sourceObjectiveStatus = "unverified-source-field" }
quests[8989] = { id = 8989, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das rechte Stück von Lord Valthalaks Amulett", description = "Ein Freund von mir, Mor Grayhoof, war der Erste, der Lord Valthalaks Amulett und dem darin enthaltenen, korrupierenden Seelenfragment zum Opfer fiel. Nachdem wir Valthalaks Zauberbuch und Amulett gestohlen hatten, flohen wir um unser Leben aus dem oberen Teil der Blackrockspitze. Während unserer überstürzten Flucht, fiel Mor in den unteren Teil der Blackrockspitze hinab.\n\nWir erfuhren später, dass er den Fall überlebt hatte und von Kriegsmeister Voone gefangengenommen und gefoltert worden war. Später schlichen sich Spektrale Assassine in die Blackrockspitze ein und erschlugen Mor vor Voones Augen.", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Mor Grayhoof zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück.", progress = "Es ist vollbracht? Ihr habt das rechte Stück von Lord Valthalaks Amulett, das Amulett wieder zusammengesetzt und dem Geist von meinem alten Kameraden, Mor Grayhoof, zu seiner ewigen Ruhe verholfen?", completion = "Ich danke Euch, {name}, dafür, dass Mor Grayhoofs Geist nun in Frieden ruht. Außerdem haben wir jetzt das wieder zusammengesetzte Amulett! Aber die schwierigste Aufgabe steht uns noch bevor.\n\nUm dieses Räuchergefäß darauf abzustimmen, Lord Valthalak herbeizurufen, werdet Ihr mir noch einige weitere Komponenten bringen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8990] = { id = 8990, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das rechte Stück von Lord Valthalaks Amulett", description = "Wir erfuhren später, während wir alle unser Bestes taten, um zu überleben, dass Isalien, eine Nachtelfenpriesterin, die unserer Gruppe angehörte, in die Heimatstadt der Urahnen der Nachtelfen zurückgekehrt war - jetzt als Düsterbruch bekannt. Demzufolge, was uns berichtet wurde, zog es sie sowohl aus persönlichen Gründen dorthin zurück, als auch weil sie die Geheimnisse ihres Stücks des Amuletts ergründen wollte.\n\nAllerdings gelang es ihr nicht, dieses Wissen zu erlangen. Wie uns zugetragen wurde, wurde sie am Schrein von Eldretharr von Alzzin dem Wildformer und seinen Schergen in einen Hinterhalt gelockt.", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Isalien zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück.", progress = "Habt Ihr etwa schon Isaliens Geist zur ewigen Ruhe gebettet und das rechte Stück von Lord Valthalaks Amuletts wiederbeschafft, {name}? Denkt daran, Lord Valthalaks Amulett wieder zusammenzusetzen, bevor Ihr es mir gebt.", completion = "Ich danke Euch, {name}, dafür, dass Ihr Isaliens Geist zur ewigen Ruhe gebettet habt. Vielleicht wird sie jetzt den Frieden ihrer Göttin erfahren. Außerdem haben wir jetzt das wieder zusammengesetzte Amulett! Aber die schwierigste Aufgabe steht uns noch bevor.\n\nUm dieses Räuchergefäß darauf abzustimmen, Lord Valthalak herbeizurufen, werdet Ihr mir noch einige weitere Komponenten bringen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8991] = { id = 8991, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das rechte Stück von Lord Valthalaks Amulett", description = "Die Geschwister, Jarien und Sothos, beschlossen, sich dem Scharlachroten Kreuzzug anzuschließen, nachdem sich unser Söldnerbund aufgelöst hatte. Das rechte Stück von Valthalaks Amulett nahmen sie mit sich. Ich war froh, sie los zu sein, aber jetzt brauchen wir dieses Stück zurück.\n\nUnseren Informationen zufolge, wurden sie vom obersten Kreuzzügler Dathrohan höchstpersönlich hingerichtet, da sie die Initiationsriten in seiner Kammer in der Scharlachroten Bastion nicht bestanden hatten. \n\nWie dem auch sei, wir, und mit \"wir\" meine ich IHR, müssen dieses Amulettstück zurückbekommen.", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um die Geister von Jarien und Sothos zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück.", progress = "Heißt das etwa, dass Ihr bereits die Geister dieser beiden Narren erlöst und die Stücke von Lord Valthalaks Amulett wieder zusammengesetzt habt, {class}?", completion = "Selbst wenn ich sie zu ihren Lebzeiten nicht mochte, ist es vermutlich das Beste, dass Ihr die Geister der Beiden endlich erlöst habt. Außerdem haben wir jetzt das wieder zusammengesetzte Amulett! Aber die schwierigste Aufgabe steht uns noch bevor.\n\nUm dieses Räuchergefäß darauf abzustimmen, Lord Valthalak herbeizurufen, werdet Ihr mir noch einige weitere Komponenten bringen müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[8992] = { id = 8992, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das rechte Stück von Lord Valthalaks Amulett", description = "Jetzt, wo wir alles beisammen haben, was wir benötigen, wird es Zeit uns darüber zu unterhalten, wen Ihr als nächstes beschwören werdet.\n\nKormok war ganz okay, für einen Oger, bis er sich der Nekromantie zuwandte. Von da ab wurde es für jeden im Bund ganz schön gruselig. Es überraschte also niemanden, dass er mit seinem Stück des Amuletts in sein neues Zuhause verschwand, Scholomance.\n\nAber selbst dort, oder vielleicht gerade dort, war er nicht vor den spektralen Assassinen sicher. Sie erschlugen ihn vor den Augen seines Meisters, Ras Frostraunen.", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um den Geist von Kormok zu beschwören und zu vernichten. Kehrt dann mit Lord Valthalaks zusammengesetzten Amulett und dem Räuchergefäß der Beschwörung zu Bodley im Blackrock zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[8993] = { id = 8993, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschenkübergabe", progress = "Seid Ihr gekommen, um Eurem liebsten Anführer ein Geschenk der Liebe und Verehrung darzubringen?", completion = "Wunderbar! Wunderbar! Ich werde es zu den anderen Geschenken auf den Haufen legen.\n\nIch habe niemals so viele erwartet! \n\nNun, lasst mich mal ein weiteres hinzuzählen..." }
quests[8994] = { id = 8994, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Letzte Vorbereitungen", description = "Wir sind nun beinah bereit, {class}. Ich brauche nur noch einige weitere Komponenten, um das Räuchergefäß darauf abzustimmen, Lord Valthalak herbeizurufen.\n\nFür den Anfang würde ich Euch darum bitten, Euch in die Blackrockspitze zu begeben und die dort heimischen Orcs zu töten. Ihre Armschienen enthalten Metallspuren, die ich benötigen werde. Da diese Armschienen nur Spuren des Metalls enthalten, werde ich eine Menge von ihnen benötigen. Um den Abstimmungsprozess abzuschließen, brauche ich weiterhin noch ein Fläschchen mit oberster Macht.\n\nViel Glück, {name}!", sourceObjective = "Bringt Bodley im Blackrock 40 Blackrockarmschienen und ein Fläschchen mit oberster Macht.", progress = "Wir haben viel durchgestanden, {name}, und ich wollte Euch nur sagen, dass ich Euch sehr dankbar bin, egal, was auch geschehen mag. Ihr habt Euch in Lebensgefahr begeben, um den überlebenden Mitgliedern unseres Söldnerbundes zu helfen. In meinen Augen seid Ihr jetzt einer von uns, ein Mitglied des Bundes der verhüllten Klinge.", completion = "Das wär's dann. Ich werde das Metall aus den Armschienen extrahieren und es in das Räuchergefäß geben. Dann wird es darauf abgestimmt sein, Lord Valthalak herbeizurufen, und Ihr könnt ihm endlich sein Seelenamulett wiedergeben.\n\nIhr habt einen weiten Weg zurückgelegt, {name}, gebt jetzt nicht auf, wo das Ende in Sicht ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8995] = { id = 8995, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mea Culpa, Lord Valthalak", description = "Die nötigen Vorbereitungen sind nun getroffen, {name}.\n\nZu seinen Lebzeiten bewohnte Lord Valthalak die Kammer, in der sich nun die Bestie aufhält. Geht dorthin und benutzt dann das Räuchergefäß der Beschwörung, um Lord Valthalak herbeizurufen. Es wird ihn wiederbeleben, also werdet Ihr ihn erneut töten müssen. Es wäre sinnvoll, zuerst die Bestie zu erledigen. Bringt außerdem genug Kameraden mit, um Euch durch den oberen Teil der Blackrockspitze zu kämpfen.\n\nBenutzt, sobald Ihr ihn ausgeschaltet habt, das Amulett bei seiner Leiche. Nachdem seine Seele wieder vollständig ist, wird er es vermutlich zurückverlangen.\n\nViel Glück!", sourceObjective = "Benutzt das Räuchergefäß der Beschwörung, um Lord Valthalak zu beschwören. Macht ihn unschädlich und benutzt dann Lord Valthalaks Amulett bei seiner Leiche. Danach werdet Ihr dem Geist von Lord Valthalak sein Amulett zurückgeben müssen.", progress = "{class}, Ihr wagt es, meine Ruhe zu stören!?", completion = "Ihr könnt Euch glücklich schätzen, dass Ihr nicht selbst der Gruppe angehört, die mir einst dieses Amulett stahl.\n\nIch werde mir jetzt das zurückholen, was mir gehört, Sterblicher! Gebt mir das Amulett!", sourceObjectiveStatus = "unverified-source-field" }
quests[8996] = { id = 8996, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Bodley", description = "Ich werde Euch Eure Unverschämtheit dieses eine Mal vergeben, {class}, da Ihr heute eine noble Tat vollbracht habt. Ihr habt mich wieder mit dem Rest meiner gestohlenen Seele vereint. Obgleich Eurer offensichtlich schwachen Natur, {race}, habt Ihr den Mut bewiesen, über den jene, die es wagten mich zu bestehlen, nicht verfügten und vermutlich niemals werden.\n\nKehret schnell zu ihnen zurück, bevor ich es mir anders überlege und Euch dort niederstrecke, wo Ihr steht. Kehret zurück und richtet ihnen aus, dass sie vor mir sicher sind... Momentan zumindest.", sourceObjective = "Bringt das Räuchergefäß der Beschwörung zurück zu Bodley im Blackrock.", progress = "{name}, Ihr seid lebendig zurückgekehrt! Dann ist ja wenigstens einer von uns noch am leben.\n\nIhr müsst mir unbedingt die ganze Geschichte erzählen!", completion = "Das hat er alles gesagt? Unglaublich, ich kann es kaum glauben, dass er die spektralen Assassine und Pirscher zurückrufen wird, auch wenn er ja dennoch andeutete, dass diese Sache noch ein Nachspiel haben könnte.\n\nHeute ist ein großartiger Tag, {name}! Ihr habt das vollbracht, zu dem nur wenige fähig sind, und habt zumindest einen Teil unserer vergangenen Sünden gesühnt.\n\nIch danke Euch! Als Zeichen meiner Dankbarkeit werde ich Euch dies hier geben. Ihr könnt es benutzen, um an den verfluchten Orten, die Ihr bereits besucht habt, Geister zu beschwören. Und sogar noch an ein paar anderen Orten!", sourceObjectiveStatus = "unverified-source-field" }
quests[8997] = { id = 8997, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Anfang", description = "Ich denke, nun wird es Zeit Lebewohl zu sagen, mein Freund. Ich werde immer hier sein, falls Ihr von Zeit zu Zeit mal mit mir reden wollt. Vielleicht ja, während Ihr auf Eure Kameraden wartet um der Blackrockspitze einen Besuch abzustatten.\n\nGeht, bevor ich noch anfange zu heulen. Geht zu Deliana in Ironforge zurück und erzählt ihr, was vorgefallen ist.", sourceObjective = "Sprecht mit Deliana am Hohen Sitz von Ironforge.", completion = "Ich bin sehr glücklich darüber, dass Ihr heil zu mir zurückgekehrt seid, {name}. Ihr seht zwar ein wenig mitgenommen aus, aber es scheint Euch gut zu gehen.\n\nErzählt mir alles, was vorgefallen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8998] = { id = 8998, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Anfang", description = "Ich denke, nun wird es Zeit Lebewohl zu sagen, mein Freund. Ich werde immer hier sein, falls Ihr von Zeit zu Zeit mal mit mir reden wollt. Vielleicht ja, während Ihr auf Eure Kameraden wartet um der Blackrockspitze einen Besuch abzustatten.\n\nGeht, bevor ich noch anfange zu heulen. Geht zu Mokvar in Orgrimmar zurück und erzählt ihm, was vorgefallen ist.", sourceObjective = "Sprecht mit Mokvar in der Feste Grommash im Tal der Weisheit von Orgrimmar.", completion = "Ich freue mich zu sehen, dass Ihr überlebt habt, {name}. Ihr seht gut aus, und auch etwas erfahrener.\n\nErzählt mir, was vorgefallen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[8999] = { id = 8999, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Beste gibt's zum Schluss", description = "Das ist ja eine unglaubliche Geschichte, {name}! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.", sourceObjective = "Gebt Deliana Eure Kutte des Wildherzens und Eure Weste des Wildherzens.", sourceObjectiveStatus = "unverified-source-field" }
quests[9000] = { id = 9000, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Beste gibt's zum Schluss", description = "Das ist ja eine unglaubliche Geschichte, {name}! Seid Euch meines Dankes gewiss, und der aufrichtigen Dankbarkeit all derer, die in dieses Abenteuer verwickelt waren. Vielleicht kann ich nun endlich wieder mit geschlossenen Augen schlafen.\n\nNun zu Eurer Belohnung. Ich habe hier einige Dinge, an denen Ihr gewiss Gefallen finden werdet.", sourceObjective = "Gebt Deliana Eure Bestienjägerkappe und Eure Bestienjägertunika.", sourceObjectiveStatus = "unverified-source-field" }
