quests[9019] = { id = 9019, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.", sourceObjective = "Kehrt mit einem Paar Sandalen des Gläubigen, einem Rock des Gläubigen und einem Mantel des Gläubigen zu Mokvar in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9020] = { id = 9020, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.", sourceObjective = "Kehrt mit einem Paar Stiefel der Schattenkunst, einer Hose der Schattenkunst und einer Schiftung der Schattenkunst zu Mokvar in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9021] = { id = 9021, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.", sourceObjective = "Kehrt mit einem Paar Sandalen der Furcht, Gamaschen der Furcht und einem Mantel der Furcht zu Mokvar in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9022] = { id = 9022, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Mokvar zurück und sagt ihm, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden. Mit ihm könnt Ihr auch über eine eventuelle Belohnung sprechen.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es dringend brauchen.", sourceObjective = "Kehrt mit einem Paar Stiefel der Ehre, Beinplatten der Ehre und einer Schiftung der Ehre zu Mokvar in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[9023] = { id = 9023, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das perfekte Gift", description = "Mein Bruder und ich sind im Ravenholdt-Anwesen für den Giftbedarf zuständig.\n\nLord Ravenholdt hat mich damit beauftragt, eine neue und extrem effektive Giftmischung zusammenzustellen, die aus den Giftbeuteln der Bewohner von Zul'Gurub und den Ruinen von Ahn'Qiraj gewonnen werden kann.\n\nEs gibt in diesen verfluchten Ruinen zwei ganz besonders giftige Bestien, die vielleicht genau das haben, wonach wir suchen, {class}. Bringt mir einen Giftbeutel der Bestien Kurinnaxx und Venoxis und wir wären Euch ewig dankbar.", sourceObjective = "Dirk Thunderwood in der Burg Cenarius will, dass Ihr ihm Venoxis' Giftbeutel und Kurinnaxx' Giftbeutel bringt.", progress = "Alleine packt Ihr das nicht, {name}. Ihr werdet Kameraden mitbringen müssen.", completion = "Ravenholdt dankt Euch, Held! Sucht Euch was aus!", sourceObjectiveStatus = "unverified-source-field" }
quests[9024] = { id = 9024, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aristans Verdacht", description = "Ich hab's! Habt Ihr den neuen Duft in den Straßen aufgeschnappt? Das neue Duftwasser und Parfüm, das gerade so angesagt ist? Unsere Wachen würden ihre Pflichten nicht so einfach vernachlässigen.\n\nZumindest nicht, solange ihre Sinne nicht von fauler Alchimie vernebelt wurden.\n\nEs gibt nur einen Weg, um ganz sicher zu sein - bringt Morgan Pestle einen Flakon von dem Parfüm und dem Duftwasser, und klärt ihn über meinen Verdacht auf. Ich werde Euch für Eure Ausgaben entschädigen, sobald Ihr zurückkommt.", sourceObjective = "Bringt 1 Duftwasserflakon und 1 Parfümflakon zu Morgan Pestle im Handelsdistrikt von Stormwind.", progress = "Kann ich Euch irgendwie behilflich sein?", completion = "Ich verstehe Aristans Bedenken, aber ich glaube wirklich, dass er überreagiert. Lasst die jungen Männer und Frauen doch einfach machen, was sie möchten. Ich denke Aristan hat vergessen, was es bedeutet, jung und verliebt zu sein.\n\nEs wäre allerdings besser, wenn Ihr ihm das nicht sagen würdet. Soll er denken, was er will.", sourceObjectiveStatus = "unverified-source-field" }
quests[9025] = { id = 9025, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morgans Entdeckung", description = "Nun... es sieht ganz so aus, als ob Aristan doch noch auf etwas gestoßen sein könnte. Ich habe Spuren von Substanzen gefunden, die in Liebestränken und gedankenverwirrenden Gebräuen verwendet werden.\n\nEs ist nicht ungewöhnlich, dass man in Parfüm derartige Spuren auffindet, allerdings sind einige der Zutaten, die ich in den Düften finden konnte, doch recht... merkwürdig.", sourceObjective = "Kehrt zu Aristan Mottar zurück, er befindet sich vor der Bank im Handelsdistrikt von Stormwind.", completion = "Obwohl ich Derartiges bereits vermutet habe, ist es dennoch beunruhigend, dass mein Verdacht sich jetzt bestätigt hat. Wir müssen unseren nächsten Schritt mit Bedacht planen.\n\nHier, nehmt dies als Entschädigung für das Duftwasser und Parfüm, das Ihr gekauft habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9026] = { id = 9026, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgung der Spur", description = "Wir müssen der Ursache auf den Grund gehen. Ich habe viel mehr Leute als sonst - einschließlich Wachen - im Gasthaus 'Die güldene Rose' ein- und ausgehen sehen. Sprecht mit Allison, sollte sie sie verkaufen, so kann sie Euch zu der Herkunft der Ware Auskunft geben.", sourceObjective = "Sprecht mit Gastwirtin Allison im Gasthaus 'Die güldene Rose' im Handelsdistrikt von Stormwind.", completion = "Oh ja, ich habe das Parfüm und Duftwasser erst seit kurzem auf Lager. Allerdings verkauft es sich so gut, dass ich nicht weiß, wie lange ich es noch in den Regalen haben werde.\n\nEhrlich gesagt, ich finde es etwas langweilig. Jeder duftet gleich? Es riecht gut, aber, naja.", sourceObjectiveStatus = "unverified-source-field" }
quests[9027] = { id = 9027, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolgung der Spur", description = "Irgendwas mit dem Duftwasser? Das ist möglich. Ich habe noch nie gesehen, dass eine Ware so begehrt war wie diese.\n\nHört mal, sollte es etwas damit auf sich haben, dann möchte ich es auch wissen. Ich habe meine Lieferung von einem Händler namens Evert Sorisam. Er ist neu in der Stadt.\n\nEr erwähnte, dass er einige Waren hätte, die er bei 'Das feinste Band' abliefern müsse.", sourceObjective = "Sprecht mit Evert Sorisam bei 'Das feinste Band' entlang der Kanäle Stormwinds.", completion = "Ja, natürlich. Diese Düfte sind die gefragtesten Waren dieser Saison. Ihr seid bereits die fünfte oder sechste Person, die innerhalb einer Stunde nach Auskunft darüber verlangt.\n\nIch befürchte, dass meine Vorräte bereits alle ausverkauft sind. Möchtet Ihr welche, solltet Ihr mit Allison sprechen, die Gastwirtin von 'Die güldene Rose'.\n\nLasst Euch aber nicht zu viel Zeit damit. Ich bin mir sicher, dass Ihr das Duftwasser unwiderstehlich finden werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9028] = { id = 9028, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lüftung des Geheimnisses", description = "Was? Verrat? Nein, nein. Ich versichere Euch, dass meine Absichten in jeder Hinsicht harmlos sind.\n\nIst es denn so falsch, denen helfen zu wollen, die dieses leidvolle Ritual des Umwerbens zu erleichtern wünschen? Kommt schon, das ist doch kein Verbrechen.\n\nIch werde Euch beweisen, dass ich keine schlechten Absichten hege, indem ich Euch meine Quelle verrate.\n\nDie Lieferung wurde mir von einem Staffron Lerent zugestellt, so eine Art Apotheker. Ich habe nie mit ihm gesprochen.\n\nUnser Goblinmittelsmann meinte, dass er im Vorgebirge von Hillsbrad gearbeitet hätte, irgendwo hinter dem unheimlichen Ravenholdt-Anwesen. Ich wünsche Euch viel Glück bei der Suche nach ihm.", sourceObjective = "Findet Apotheker Staffron Lerent hinter dem Ravenholdt-Anwesen im Vorgebirge von Hillsbrad.", completion = "Ja, ich habe diese Düfte hergestellt. Sie duften wunderbar, nicht war? Unwiderstehlich.\n\nSobald die Krieger von Allianz und Horde gleichermaßen von Gefühlen der Liebe hingerissen sind, werden sie dem Aufstieg des Schattenrates machtlos gegenüber stehen.\n\nSie werden geschwächt und unvorbereitet sein. Da sie um ihre Liebsten besorgt sind, werden sie die Kontrolle verlieren.\n\nDie Lösung war so einfach. Warum bin ich nicht schon eher darauf gekommen? Die Schwäche aller liegt im Herzen. Es gibt nichts, was Ihr tun könntet, um das Unvermeidbare aufzuhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9029] = { id = 9029, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein blubbernder Kessel", sourceObjective = "Ein angenehmer Duft geht von dem Kessel auf.", sourceObjectiveStatus = "unverified-source-field" }
quests[9030] = { id = 9030, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Sprecht mit Deliana in Eisenschmiede.\n\nBereitgestellter Gegenstand:", sourceObjectiveStatus = "unverified-source-field" }
quests[9031] = { id = 9031, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anthions Abschiedsworte", description = "Valthalaks Seele wurde in diesem Amulett verwahrt. In unserer Gier haben wir es wie Narren in drei Teile aufgeteilt ohne um den Fluch zu wissen, der uns heimsuchen würde.\n\nDie einzige Möglichkeit, den Fluch aufzuheben, besteht darin das Amulett wieder zusammenzusetzen. Kehrt zu Deliana zurück und sagt ihr, dass Bodley unsere einzige Hoffnung ist, die einzelnen Teile wiederzufinden.\n\nIch selbst kann nun endlich in Frieden ruhen. Ich wünsche Euch viel Glück, Ihr werdet es brauchen.", sourceObjective = "Sprecht mit Mokvar in Orgrimmar.", sourceObjectiveStatus = "unverified-source-field" }
quests[9032] = { id = 9032, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bodleys trauriges Schicksal", description = "Das Amulett enthielt Lord Valthalaks Seele? Dann ist es nicht weiter verwunderlich, dass es mit einem solch machtvollen Fluch belegt war.\n\nBodley aufzufinden, könnte sich allerdings schwierig gestalten. Als ich das letzte Mal von ihm hörte, wollte er in die Blackrockspitze zurückkehren. Seitdem hat niemand jemals wieder etwas von ihm gehört.\n\nSucht ihn in der Blackrockspitze, aber ich befürchte, dass er bereits tot ist. Ich würde Euch empfehlen, den Apparat des Goblins mitzunehmen.", sourceObjective = "Reist zum Blackrock und benutzt den extradimensionalen Geisterdetektor, um Bodley nahe der Blackrockspitze zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9033] = { id = 9033, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echo des Krieges", description = "Fünf Jahre sind seit dem letzten Krieg vergangen...\n\nZehntausende mussten dabei ihr Leben lassen - und für was? Die Bedrohung wurde niemals gänzlich ausgelöscht.\n\nJetzt verbreitet der Lichkönig erneut Angst und Schrecken... sein getreuer Jünger, Kel'Thuzad, zieht seine Truppen für einen weiteren Angriff auf unser Land zusammen.\n\nWir werden es nicht zulassen! Beweist Euer Engagement. Zeigt, dass Ihr gewillt seid, Leib und Leben zu riskieren, um diesen Wahnsinn aufzuhalten! Die vereinigte Macht der Argentumdämmerung und des Kreuzzugs wird Euch mit allen Mitteln zur Seite stehen.\n\nGeht nach Naxxramas und zerstört die Geißel...", sourceObjective = "Kommandant Eligor Dawnbringer bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte, dass Ihr 5 lebende Monstrositäten, 5 Steinhautgargoyles, 8 Captains der Todesritter und 3 Giftpirscher tötet.", completion = "Ihr habt ausgezeichnete Arbeit geleistet! Ihr werdet mittels der Dienste der Männer und Frauen bei der Kapelle entlohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[9034] = { id = 9034, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Brustplatte des Schreckenspanzers", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.", sourceObjective = "Korfax bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch eine Brustplatte des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Brustplatte, 25 kampfzerschlissene Plattenstücke, 4 Arkanitbarren und 2 Nexuskristalle.", sourceObjectiveStatus = "unverified-source-field" }
quests[9036] = { id = 9036, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beinplatten des Schreckenspanzers", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.", sourceObjective = "Korfax bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Beinplatten des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinplatten, 20 kampfzerschlissene Plattenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9037] = { id = 9037, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Helm des Schreckenspanzers", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.", sourceObjective = "Korfax bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch einen Helm des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihter Helm, 15 kampfzerschlissene Plattenstücke, 5 Arkanitbarren und 1 Nexuskristall.", sourceObjectiveStatus = "unverified-source-field" }
quests[9038] = { id = 9038, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schulterstücke des Schreckenspanzers", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.", sourceObjective = "Korfax bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Schulterstücke des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Schulterstücke, 12 kampfzerschlissene Plattenstücke, 2 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9039] = { id = 9039, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabatons des Schreckenspanzers", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.", sourceObjective = "Korfax bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Sabatons des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Sabatons, 12 kampfzerschlissene Plattenstücke, 2 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", progress = "Unterschätzt niemals ein gutes Paar Stiefel. Besonders, wenn sie von Korfax angefertigt wurden!", completion = "Ich habe Mograine im letzten Krieg dabei beobachtet, wie er die stinkenden Schädel der lebenden Toten mit genau diesen Stiefel gespalten hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[9040] = { id = 9040, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Stulpen des Schreckenspanzers", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.", sourceObjective = "Korfax bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Stulpen des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Stulpen, 8 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.", progress = "Diese Stulpen sind für das Tragen einer edlen Waffe geschaffen.", completion = "Möge sich Euer Griff um den Hals Kel'Thuzads festigen.\n\n<Korfax macht eine reißende Bewegung mit seinen Händen.>", sourceObjectiveStatus = "unverified-source-field" }
quests[9041] = { id = 9041, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Taillenschutz des Schreckenspanzers", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.", sourceObjective = "Korfax bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch einen Taillenschutz des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Taillenschutz, 8 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.", progress = "Der Gürtel steht für Modebewusstsein und schützende Ausrüstung zugleich.", completion = "Verwendet ihn als Schlinge für Eure Gegner... und tragt ihn gut sichtbar beim Besuch Eurer Goblindisko. Ihr werdet das Tagesgespräch der Stadt sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[9042] = { id = 9042, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armschienen des Schreckenspanzers", description = "Solltet Ihr während Euren Kämpfen gegen die Geißel in Naxxramas auf entweihte Rüstungsteile und kampfzerschlissene Plattenstücke stoßen, bringt sie zu mir, und ich werde Euch ein Rüstungsteil anfertigen, das eines Heldens würdig ist.", sourceObjective = "Korfax bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Armschienen des Schreckenspanzers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Armschienen, 6 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 1 Nexuskristall.", progress = "Die Handgelenke sind die zweitverletzlichste Stelle des Körpers... oder ist es die vierte?", completion = "Denkt daran, die Handgelenke sind die fünftverletzlichste Stelle des Körpers! Schützt Eure Handgelenke und sie werden ganz sicher Eure Ellbogen schützen - vielleicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[9043] = { id = 9043, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tunika der Erlösung", description = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.", sourceObjective = "Kommandant Eligor Dawnbringer bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch eine Tunika der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Plattenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9044] = { id = 9044, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beinschützer der Erlösung", description = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.", sourceObjective = "Kommandant Eligor Dawnbringer bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Beinschützer der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinschützer, 20 kampfzerschlissene Plattenstücke, 4 Arkanitbarren und 2 Nexuskristalle.", progress = "Ihr werdet keine Beinschützer finden, die besser zu einem gesegneten Kämpfer passen.", completion = "Diese Beinschützer bewahren das Gleichgewicht zwischen dem Kampf mit der Waffe und mit Magie.", sourceObjectiveStatus = "unverified-source-field" }
quests[9045] = { id = 9045, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfstück der Erlösung", description = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.", sourceObjective = "Kommandant Eligor Dawnbringer bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch ein Kopfstück der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihtes Kopfstück, 15 kampfzerschlissene Plattenstücke, 5 Arkanitbarren und 2 geschmeidige unverwüstliche Bälge.", progress = "<Eligor sieht zu Euch auf und wendet sich dann wieder seinem Gespräch zu.>", completion = "<Eligor zeigt auf seinen Kopf.>\n\nBehaltet Euren Schutz stets auf, {class}.", sourceObjectiveStatus = "unverified-source-field" }
