quests[9049] = { id = 9049, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gurt der Erlösung", description = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.", sourceObjective = "Kommandant Eligor Dawnbringer bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch einen Gurt der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Gurt, 8 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 3 Nexuskristalle.", sourceObjectiveStatus = "unverified-source-field" }
quests[9050] = { id = 9050, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handgelenksschutz der Erlösung", description = "Ihr werdet die Überbleibsel von unseren gefallenen Helden bei den Körpern der Obersten von Naxxramas finden. Bringt mir diese entweihten Vermächtnisse, kampfzerschlissene Plattenstücke und die Handwerksmaterialien, die zum Wiederherstellen der verfluchten Rüstung benötigt werden, damit ich Euch eine prächtige Ausstattung anfertigen kann.", sourceObjective = "Kommandant Eligor Dawnbringer bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch einen Handgelenksschutz der Erlösung anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Handgelenksschutz, 6 kampfzerschlissene Plattenstücke, 1 Arkanitbarren und 2 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9051] = { id = 9051, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Giftexperiment", description = "Das Gift, das Ihr mir geholfen habt zu entwickeln, ist für einen bestimmten Zweck gedacht. Die mächtigen Teufelssaurier des Kraters erschweren mir die Jagd und das Überleben. Selbst wenn ich über die nötige Stärke verfügen würde, einen Teufelssaurier zu erlegen, würde einfach nur ein anderer sein Territorium beanspruchen.\n\nNehmt diesen vergifteten Widerhaken und stecht ihn tief in einen lebenden Teufelssaurier. Das Gift sollte ihn ruhigstellen, aber ich bin mir nicht sicher, wie lange es dauern wird, bis es wirkt...", sourceObjective = "Stecht einen Teufelssaurier mit dem Teufelssaurierhaken.", completion = "Ich danke Euch, {name}. Ihr seid tapfer und weise.\n\nSagt mir, wie hat der Teufelssaurier auf das Gift reagiert?", sourceObjectiveStatus = "unverified-source-field" }
quests[9052] = { id = 9052, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blutblütengift", description = "Ich würde Euch darum bitten, mir dabei behilflich zu sein, ein spezielles Gift zu entwickeln, um eine der mächtigsten Kreaturen des Kraters ruhigzustellen. Es ist nicht tödlich und nur die scharfen Augen eines {class} könnten die nötigen Zutaten dafür erspähen.\n\nDie Blutkappenpilze wachsen in den Blutblütensprösslingen, die überall im Krater anzufinden sind. Gorishistachel könnt Ihr von den Riesenwespen erhalten, die in der und um die wuchernde Narbe herum heimisch sind. Sie befindet sich im südlichen Teil des Kraters.", sourceObjective = "Sammelt Blutkappenpilze und Gorishistachel und kehrt zu Torwa Pathfinder im Un'Goro Krater zurück.", progress = "Hattet Ihr Erfolg?", completion = "Endlich habe ich die nötigen Zutaten!\n\nZusammen mit der Un'Goro-Erde, die ich schon selbst gesammelt habe, sollte sich das Gift nun einfach herstellen lassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[9053] = { id = 9053, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine bessere Zutat", description = "Genau wie ich befürchtet hatte - das Gift ist einfach zu schwach für eine solch mächtige Kreatur.\n\nUm ein Gift von ausreichender Potenz zu entwickeln, werdet Ihr Euch auf den Grund des Tempels von Atal'Hakkar begeben müssen. Enträtselt dort das Geheimnis des Altars und nehmt dem Wächter eine Fäulnisranke ab. Der Tempel ist gefährlich und es wird vermutlich erforderlich sein, Gefährten mitzubringen.\n\nKehrt zu mir zurück, wenn Ihr fertig seid.", sourceObjective = "Beschafft Euch eine Fäulnisranke von dem Wächter auf dem Grund des versunkenen Tempels und kehrt zu Torwa Pathfinder zurück.", progress = "Habt Ihr die Fäulnisranke?", completion = "Endlich werde ich ein wirksames Gift herstellen können. Ich will es Euch nicht erneut auferlegen, die Kreatur damit zu vergiften, da ich schon zu tief in Eurer Schuld stehe.\n\nSeid Euch meines Danks und meines Respekts gewiss. Mögen Eure Reisen immer gut verlaufen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[9054] = { id = 9054, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tunika des Gruftpirschers", description = "Ich habe eine Verwendung für den Panzer der Gruftsatanskreatur gefunden. Ich bin in der Lage ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente der Gruftsatanskreaturen mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", sourceObjective = "Jäger Leopold bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch eine Tunika des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Kettenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9055] = { id = 9055, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beinschützer des Gruftpirschers", description = "Ich habe eine Verwendung für den Panzer der Gruftsatanskreatur gefunden. Ich bin in der Lage ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente der Gruftsatanskreaturen mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", sourceObjective = "Jäger Leopold bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Beinschützer des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Beinschützer, 20 kampfzerschlissene Kettenstücke, 3 Arkanitbarren und 5 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9056] = { id = 9056, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kopfstück des Gruftpirschers", description = "Ich habe eine Verwendung für den Panzer der Gruftsatanskreatur gefunden. Ich bin in der Lage ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente der Gruftsatanskreaturen mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", sourceObjective = "Jäger Leopold bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch ein Kopfstück des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihtes Kopfstück, 15 kampfzerschlissene Kettenstücke, 4 Arkanitbarren und 2 Nexuskristalle.", progress = "Habt Ihr die Gegenstände, um die ich Euch gebeten habe, {class}?", completion = "Ihr verwandelt Euch in eine furchterregende Kreatur, {name}.", sourceObjectiveStatus = "unverified-source-field" }
