quests[9061] = { id = 9061, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handgelenksschutz des Gruftpirschers", description = "Ich habe eine Verwendung für den Panzer der Gruftsatanskreatur gefunden. Ich bin in der Lage ein extrem leichtes und äußerst tödliches Rüstungsset anzufertigen, indem ich die Fragmente der Gruftsatanskreaturen mit einigen entweihten Rüstungsteilen aus Naxxramas kombiniere.\n\nBringt mir die benötigten Gegenstände und ich werde eine Rüstung für Euch anfertigen, wie man sie auf dieser Welt noch nicht gesehen hat!", sourceObjective = "Jäger Leopold bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch einen Handgelenksschutz des Gruftpirschers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Handgelenksschutz, 6 kampfzerschlissene Kettenstücke, 1 Arkanitbarren und 2 geschmeidige unverwüstliche Bälge.", progress = "Habt Ihr die Gegenstände, um die ich Euch gebeten habe, {class}?", completion = "Der Handgelenksschutz ist fertig. Viel Spaß damit!", sourceObjectiveStatus = "unverified-source-field" }
quests[9063] = { id = 9063, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Torwa Pathfinder", description = "Ein Jäger names Torwa Pathfinder hat die Hilfe eines Druiden angefordert. Er sagte, dass nur einer von uns über den nötigen Respekt für die Natur und die Fähigkeiten verfügen würde, um ihm zu helfen.\n\nEs gibt einen Pfad, der den Un'Goro Krater und die Tanariswüste verbindet. Ihr werdet Torwa nahe dem Punkt finden, an dem der Pfad in den Krater hineinführt.", sourceObjective = "Sprecht im Un'Goro Krater mit Torwa Pathfinder.", completion = "Ihr seid weit gereist, um mich zu treffen, {class}, und Ihr kommt genau zur rechten Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[9065] = { id = 9065, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The \"Chow\" Quest (123)aa" }
quests[9068] = { id = 9068, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tunika des Erdspalters", description = "Würdet Ihr mir die Ehre erweisen und mir die Rüstungen derer bringen, die bei der Verteidigung dieses Landes gefallen sind?\n\nDie Rüstungen wurden entweiht und zweifellos für Böses missbraucht; allerdings können sie mit kampfzerschlissenen Rüstungsstücken erneuert werden und somit noch einmal im Kampf getragen werden.\n\nBringt mir die Überbleibsel der Gefallenen, sowie die läuternden Materialien, dann soll Erdspalter Euer sein.\n\nSucht in Naxxramas.", sourceObjective = "Rimblat Erdspalter bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch eine Tunika des Erdspalters anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihte Tunika, 25 kampfzerschlissene Kettenstücke, 4 Arkanitbarren und 3 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
