quests[9093] = { id = 9093, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handgelenksschutz des Traumwandlers", description = "Im letzten Krieg sind zahllose Helden umgekommen und auch heute fallen der Geißel täglich noch viele weitere Streiter zum Opfer. Den Körpern der Gefallenen werden die Rüstungen entwendet und zurück nach Naxxramas gebracht, um dort für unbekannte Zwecke missbraucht zu werden.\n\nMacht die entweihten Rüstungsteile und kampfzerschlissene Rüstungsstücke ausfindig. Besorgt mir zusätzlich die anderen Bestandteile, die ich benötige, dann werde ich eine Rüstung des Traumwandlers für Euch anfertigen.", sourceObjective = "Rayne bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch einen Handgelenksschutz des Traumwandlers anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 entweihten Handgelenksschutz, 6 kampfzerschlissene Lederstücke, 1 Arkankristall und 2 geschmeidige unverwüstliche Bälge.", sourceObjectiveStatus = "unverified-source-field" }
quests[9094] = { id = 9094, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handschuhe der Argentumdämmerung", progress = "Bringt Ihr mir dreißig nekrotische Runen, gebe ich Euch im Gegenzug einen Handschutz Eurer Wahl dafür. Dieser sollte sich in Eurem Kampf gegen die untote Geißel als sehr nützlich erweisen.", completion = "Ihr habt gute Arbeit geleistet, {name}. Nehmt den von Euch gewählten Handschutz als Dank für Eure Mühen." }
quests[9095] = { id = 9095, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostfeuerrobe", description = "Als Behüterin hatte ich Zugang zu Vielem von Medivhs persönlicher Habe. Die Folianten waren für micht die aufschlussreichsten Gegenstände. Während die Mehrheit der Bücher aus - sagen wir es ganz offen - Schund bestand, gab es auch einige Schmuckstücke darunter. Einer dieser Folianten beschrieb die Herstellung eines Rüstungssets, passend für einen Erzmagier: Frostfeuer.\n\n<Angela deutet auf ihren Kopf.>\n\nEs ist alles hier drin und ich bin bereit, die Früchte dieses Wissens mit Euch zu teilen, solange Ihr mir die nötigen Materialien besorgt.", sourceObjective = "Erzmagierin Angela Dosantos bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch eine Frostfeuerrobe anfertigen, wenn Ihr ihr folgende Gegenstände bringt: 1 entweihte Robe, 25 kampfzerschlissene Stoffstücke, 4 Einheiten Mondstoff und 2 Nexuskristalle.", progress = "Mit den erforderlichen Materialien und Reagenzien bin ich in der Lage, die mythische Frostfeuerrüstung wieder herzustellen.", completion = "Vergesst nicht, dass unkontrollierte Macht genauso zerstörerisch wie ungenutzte Macht ist, {class}. Lasst Vorsicht walten, wenn Ihr Frostfeuer tragt.", sourceObjectiveStatus = "unverified-source-field" }
