quests[9118] = { id = 9118, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bindungen des Glaubens", description = "<Vater Montoy vollführt vor Euch ein paar merkwürdige Gesten in der Luft.>\n\n<Gesegneter Junge/Gesegnetes Mädchen>, habt Ihr die Gewänder der Gefallenen gefunden? Die armen Seelen, die ihre letzten Atemzüge auf dem Schlachtfeld ausgehaucht haben - um alles beraubt, einschließlich ihrer Würde.\n\nBringt mir die entweihten Überbleibsel der Verstorbenen, sowie die Reagenzien zur Läuterung... auf dass Ihr mit Glauben erfüllt werdet.", sourceObjective = "Vater Inigo Montoy bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird für Euch Bindungen des Glaubens anfertigen, wenn Ihr ihm folgende Gegenstände bringt: 1 Paar entweihte Bindungen, 6 kampfzerschlissene Stoffstücke, 1 Arkankristall und 1 Nexuskristall.", progress = "Habt Ihr mir die benötigten Bestandteile gebracht, Kind?", completion = "Die Ausrüstung ist fertig, {name}. Vernichtet diejenigen mit Eurem Feuer der Rechtschaffenheit, die unserer Welt schaden wollen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9120] = { id = 9120, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Niedergang Kel'Thuzads", description = "Das Phylakterium ist alles, was vom Herrscher Naxxramas' übrig bleibt. Nach Eurem pflichtgemäßen Ermessen, müsstet Ihr das Phylakterium zerstören, um somit einem erneuten Aufbäumen des Lichs vorzubeugen. Glücklicherweise hört Ihr nur selten auf Eure innere Stimme der Vernunft.\n\nBei der Kapelle des hoffnungsvollen Lichts wird Euch irgendjemand mit Sicherheit ein Vermögen für dieses Artefakt bezahlen. Wen kümmert es schon, ob Kel'Thuzad eines Tages wieder von Neuem erstarkt?", sourceObjective = "Bringt Kel'Thuzads Phylakterium zu der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "HEILIGES LICHT! Was ist denn in Euch gefahren, Junge?", completion = "Ich hätte mir nie erträumt, dass ich das eines Tages mal zu Gesicht bekommen sollte...\n\n<Vater Montoy scheint lüstern zu geifern.>\n\nOh ja, Ihr sollt entlohnt werden, mein Junge. Reichlich entlohnt. Gebt es mir. Jetzt!", sourceObjectiveStatus = "unverified-source-field" }
quests[9121] = { id = 9121, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zitadelle des Schreckens - Naxxramas", description = "Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch dort hineinzugelangen von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichte gemacht. Zumindest war es bis heute so.\n\nWir haben einen Weg gefunden, wie wir uns mit Hilfe von arkaner Tarnung Zugang verschaffen können - einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Da es an Eurer Hingabe für die Ziele der Argentumdämmerung noch etwas mangelt, {name}, wird der Preis hoch sein. Es steht Euch frei abzulehnen und noch einmal für einen günstigeren Preis wiederzukehren, sobald Euer Ruf respektvoll oder ehrfürchtig ist.", sourceObjective = "Erzmagierin Angela Dosantos bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 5 Arkankristalle, 2 Nexuskristalle, 1 rechtschaffene Kugel und 60 Goldstücke. Euer Ruf bei der Argentumdämmerung muss außerdem wohlwollend sein.", progress = "Keiner von denen, die Naxxramas betreten haben, hat überlebt, um davon berichten zu können.", completion = "Ihr werdet ein leichtes Prickeln verspüren, {name}. Dieses Gefühl ist das Zeichen dafür, dass es funktioniert. Sobald das Ganze abgeschlossen ist, werdet Ihr Naxxramas durch das Runenportal im Pestwald betreten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9122] = { id = 9122, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zitadelle des Schreckens - Naxxramas", description = "Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch dort hineinzugelangen von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichte gemacht. Zumindest war es bis heute so.\n\nWir haben einen Weg gefunden, wie wir uns mit Hilfe von einer Art dauerhaften arkanen Tarnung Zugang verschaffen können - einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Diese Tarnung ist allerdings sehr kostspielig. Da Eure Hingabe für die Ziele der Argentumdämmerung bewundernswert ist, sind wir gewillt, einige dieser Kosten für Euch zu übernehmen.", sourceObjective = "Erzmagierin Angela Dosantos bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 2 Arkankristalle, 1 Nexuskristall und 30 Goldstücke. Euer Ruf bei der Argentumdämmerung muss außerdem respektvoll sein.", progress = "Keiner von denen, die Naxxramas betreten haben, hat überlebt, um davon berichten zu können.", completion = "Ihr werdet ein leichtes Prickeln verspüren, {name}. Dieses Gefühl ist das Zeichen dafür, dass es funktioniert. Sobald das Ganze abgeschlossen ist, werdet Ihr Naxxramas durch das Runenportal im Pestwald betreten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9123] = { id = 9123, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Zitadelle des Schreckens - Naxxramas", description = "Inmitten des Pestwalds liegt der Eingang zu der Zitadelle des Schreckens von Naxxramas. Bisher wurde jeglicher Versuch dort hineinzugelangen von den magischen Schutzzaubern, die über das Runenportal verhängt wurden, zunichte gemacht. Zumindest war es bis heute so.\n\nWir haben einen Weg gefunden, wie wir uns mit Hilfe von einer Art dauerhaften arkanen Tarnung Zugang verschaffen können - einem von mir leicht abgewandelten alten Zauber der Kirin Tor. Diese Tarnung ist allerdings sehr kostspielig. Da Eure Hingabe für die Ziele der Argentumdämmerung jedoch unerschütterlich ist, werden wir Euch sämtliche Kosten erlassen.", sourceObjective = "Erzmagierin Angela Dosantos bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird Euch die arkane Tarnung kostenfrei gewähren. Euer Ruf bei der Argentumdämmerung muss ehrfürchtig sein.", completion = "Ihr werdet ein leichtes Prickeln verspüren, {name}. Dieses Gefühl ist das Zeichen dafür, dass es funktioniert. Sobald das Ganze abgeschlossen ist, werdet Ihr Naxxramas durch das Runenportal im Pestwald betreten können.", sourceObjectiveStatus = "unverified-source-field" }
quests[9124] = { id = 9124, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was man für Gruftpirscherrüstung braucht...", description = "Würdet Ihr Euch gerne eine dieser glänzenden Münzen verdienen?\n\n<Leopold hält eine Insignie des Kreuzzugs in die Höhe.>\n\nIch habe ein kleines Problem, bei dem Ihr mir vielleicht behilflich sein könntet, {name}. Seht Ihr, ich fertige Gruftpirscherrüstung für diejenigen an, die dämlich genug sind, um sich nach Naxxramas zu wagen. Während sie mich mit den wichtigsten Bestandteilen für die Rüstung versorgen, gehen mir dennoch ständig die Teile von Gruftsatanskreaturen aus. Bringt mir einen Schwung dieser Teile und ich werde Euch dafür mit einer Insignie bezahlen - einlösbar bei dem Rüstmeister.", sourceObjective = "Jäger Leopold bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 30 Teile einer Gruftsatanskreatur.", progress = "Wie geht es mit der Jagd voran?", completion = "Ah, die werden sich gut eignen, {name}. Vergesst nicht, ich nehme jederzeit noch mehr Teile entgegen. Für jede Ladung, die Ihr mir bringt, belohne ich Euch mit einer Insignie.", sourceObjectiveStatus = "unverified-source-field" }
quests[9125] = { id = 9125, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teile einer Gruftsatanskreatur", progress = "Ihr habt mit dem ersten Schwung vorbildliche Arbeit geleistet, {name}. Solltet Ihr noch mehr Teile haben, nehme ich sie Euch jetzt ab. Für jede abgelieferte Ladung werde ich Euch mit einer Insignie belohnen.", completion = "Ausgezeichnet, {name}! Hierfür wird man mit Sicherheit gute Verwendung finden." }
quests[9126] = { id = 9126, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochensensenjagd", description = "Don Julios Muster für die Rüstung der Knochensense benötigt Knochenfragmente - ein Menge Knochenfragmente. Diejenigen, die verrückt genug sind, um sich nach Naxxramas zu wagen, versorgen mich bereits mit den wichtigsten Bestandteilen für die Rüstung. Allerdings halte ich stets nach weiteren Knochenfragmenten Ausschau.\n\nWas denkt Ihr? Würdet Ihr Euch gerne die Hände schmutzig machen und dabei ein paar Anhänger der Geißel vernichten? Hierbei kommt jeder gut davon.", sourceObjective = "Rohan der Assassine bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 30 Knochenfragmente.", progress = "Ich kann Euch die Richtung zu Orten weisen, die von Skeletten heimgesucht werden, {class}.", completion = "Ihr seid schnell, {name}. Schnell wie der Wind... Sagt mal, habe ich Euch schon von meiner Zeit in dem Barbershop-Quartett erzählt?\n\nErinnert mich das nächste Mal daran, Euch davon zu berichten.", sourceObjectiveStatus = "unverified-source-field" }
quests[9127] = { id = 9127, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenfragmente", progress = "Ein Mann meines Berufsstandes kann niemals zu viele Knochenfragmente besitzen, {name}. Kommt zu mir, wann immer Ihr einen Überschuss an Fragmenten habt, ich tausche sie dann gegen eine weitere Insignie ein.", completion = "Mein Traum von einer Karriere als professioneller Tänzer in der Disko von Gadgetzan wird sich schon bald verwirklichen! Gute Arbeit, weiter so, {name}." }
quests[9128] = { id = 9128, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Elementargleichung", description = "Seid gegrüßt, Abenteurer! Hättet Ihr Interesse an Arbeit? Wer für mich arbeitet, wird mit Insignien bezahlt. Diese Insignien können beim Rüstmeister für mächtige Gegenstände eingetauscht werden.\n\nEure Aufgabe besteht darin, mir so viele Kerne der Elemente zu bringen, wie Ihr tragen könnt. Je mehr, umso besser!\n\nIhr findet sie bei Elementaren verschiedenster Form und Größe, wie es sie überall in unserer Welt gibt.", sourceObjective = "Erzmagierin Angela Dosantos bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 30 Kerne der Elemente.", progress = "Ich kann Euch lediglich die Richtung weisen, {name}.", completion = "Ausgezeichnete Arbeit, {name}! Hier, wie versprochen Eure Insignie. Vergesst nicht, wo das hier herkommt, gibt es noch mehr...", sourceObjectiveStatus = "unverified-source-field" }
quests[9129] = { id = 9129, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kern der Elemente", progress = "Glaubt mir, ich verwende diese Kerne zum Anfertigen von Frostfeuerrüstungen. Es ist die Rüstung, die von Magiern getragen wird, die in Naxxramas kämpfen. Ohne Euch und Euresgleichen, würden wir diesen Krieg höchstwahrscheinlich verlieren.\n\nBringt Ihr mir auch weiterhin mehr Kerne, so werde ich Euch dafür wieder mit Insignien entlohnen.", completion = "Ihr erweist uns einen großen Dienst, {name}. Gut gemacht!" }
quests[9131] = { id = 9131, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bindung des Schreckenspanzers", description = "Habt Ihr jemals eine Rüstung des Schreckenspanzers zu Gesicht bekommen, {class}? Nein, natürlich nicht. Ihr seid immer noch ein <Junge/Mädchen> - ein Dreikäsehoch eben. Ich muss Euch sagen, es ist herrlich.\n\nIhr fragt Euch wahrscheinlich was all das mit Euch zu tun haben soll, richtig? Hört gut zu, Anfänger; ich brauche Dunkeleisenfragmente und bin bereit zu zahlen, um an so viele Stücke wie möglich zu kommen.\n\nIch benötige die Fragmente für das Zusammensetzen der Schreckenspanzer für unsere Helden. Bringt mir Fragmente, dann werdet Ihr bezahlt.", sourceObjective = "Korfax bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 30 Dunkeleisenfragmente.", progress = "<Korfax faucht Euch an.>\n\nWas wollt Ihr? Eine Wegbeschreibung? Wenn es weiter nichts ist...", completion = "Das sollte genügen, zumindest vorläufig. Solltet Ihr mehr haben... Ihr wisst, wo Ihr mich finden könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9132] = { id = 9132, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dunkeleisenfragmente", progress = "Ich gebe Euch für jede Ladung Dunkeleisenfragmente eine Insignie - je mehr, umso besser. Geht mir jetzt aus den Augen, bevor ich Euch noch zweiteile!", completion = "Das ist alles, was Ihr mir gebracht habt? Vielleicht habt Ihr mich das erste Mal ja nicht richtig verstanden. Ich brauche MEHR!" }
quests[9136] = { id = 9136, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildpflanzen", description = "Ich fertige für die mutigen Helden, die sich nach Naxxramas begeben, eine spezielle Rüstung an - die Rüstung des Traumwandlers. Sie versorgen mich zwar schon mit den meisten Materialien, die ich dafür benötige, aber ich halte dennoch nach jenen Ausschau, die in der Lage sind, mir Wildwedel aus dem Pflanzenreich unserer Welt zu besorgen.\n\nIhr denkt vielleicht, dass diese Aufgabe unter Eurer Würde ist, aber ohne diese Wedel kann die Rüstung nun mal nicht hergestellt werden.\n\nIch bin außerdem in der einzigartigen Lage, Euch mit einer Insignie Eurer Wahl zu bezahlen, da mich die Argentumdämmerung und der Kreuzzug mit den entsprechenden Mitteln unterstützen.", sourceObjective = "Rayne bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 30 Wildwedel.", progress = "Ich bin mit dem Pflanzenreich unserer Welt sehr vertraut. Braucht Ihr Richtungsangaben?", completion = "Ich bin Euch sehr verbunden, {name}.\n\n\n\nBitte denkt daran, dass ich jederzeit Wedel entgegennehme.", sourceObjectiveStatus = "unverified-source-field" }
quests[9137] = { id = 9137, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wildwedel", progress = "Für jeden Bündel Wildwedel, den Ihr bei mir abliefert, werde ich Euch mit einer von Euch gewählten Insignie, die der Dämmerung oder die des Kreuzzugs, bezahlen.\n\nDie Insignien können beim Rüstmeister für vielerlei Belohnungen eingetauscht werden.", completion = "Danke, {name}. Eure Arbeit ist für den Erfolg unseres Feldzugs gegen die Geißel unerlässlich." }
quests[9141] = { id = 9141, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie nennen mich \"den Schleifer\"", description = "Ihr wollt eine Verfügung? Ihr erwartet von mir, Euch eine heißbegehrte Arbeitsanweisung einfach so auszuhändigen? Ich glaube nicht, Knirps. Handwerker aus der ganzen Welt bewerben sich um Aufträge hier an der Front.\n\nWenn Ihr eine Arbeitsanweisung wollt, zeigt mir, dass Ihr gewillt seit, für die Sache zu bluten! Bringt mir eine Ehrenmarke, dann können wir darüber reden.\n\nUnd es gibt nur einen Weg, so eine Marke in Eure schmutzigen kleinen Pfoten zu bekommen - geht kämpfen.", sourceObjective = "Einsatzkommandant Metz in der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte eine Ehrenmarke der Argentumdämmerung.", progress = "<Einsatzkommandant Metz kaut auf seiner Zigarre.>\n\nWas gibt's? Ich bin ein vielbeschäftigter Mann.", completion = "In Ordnung, so funktioniert's: Für jede Ehrenmarke, die Ihr abgebt, gebe ich Euch eine Verfügung. Ihr führt die Anweisung auf dieser Verfügung aus und liefert die Waren an Rottenkommandant Stonebruiser. Kapiert? Dann raus mit Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[9142] = { id = 9142, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung", progress = "Ihr wisst wie's geht, Kind. Für eine Ehrenmarke bekommt Ihr eine Handwerksverfügung.", completion = "Ihr habt's verdient, Anfänger. Beschwert Euch also nicht. Erfüllt Euren Auftrag oder lasst es bleiben." }
quests[9153] = { id = 9153, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bedrohliche Schatten", description = "Die schwebenden Nekropolen der Geißel belagern gleichermaßen die Territorien der Horde und der Allianz. Tanaris, die verwüsteten Lande, Winterspring und die brennende Steppe erzittern unter den Schatten der fliegenden Festungen.\n\nNur durch unser gemeinsames Handeln, können wir sie zurückschlagen.\n\nDie Nekropolen werden durch magische Zirkel unterstützt, die sich an verschiedenen Punkten in den angegriffenen Gebieten befinden. Wir haben herausgefunden, dass wir die Verteidigung rund um die Zirkel zerstören können, indem wir die geistlosen Horden, die diese Zirkel umringen, vernichten.", sourceObjective = "Seht auf Eure Karte, um von der Geißel angegriffene Gebiete ausfindig zu machen. Geht dorthin und beschädigt eine Nekropole, indem Ihr die sie umgebenden Truppen der Geißel besiegt. Bringt 10 ihrer nekrotischen Runen zu Kommandant Thomas Helleran bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Es wird einige Zeit dauern, bis wir diese Bedrohung überwunden haben. Wie ist es Euch ergangen, {name}?", completion = "Ihr habt Euch sehr gut geschlagen, {name}. Die vielen Niederlagen werden letztlich den Fall der Geißel herbeiführen.\n\nRuht Euch etwas aus und erholt Euch. Schon bald müsst Ihr wieder an die Front zurückkehren, damit wir unsere gerade gewonnene Stellung nicht wieder verlieren.\n\nUm Euch bei Euren zukünftigen Kämpfen zu unterstützen, werden wir Euch einen unserer speziellen Gegenstände zur Verfügung stellen, sobald Ihr uns mehr nekrotische Runen bringt.", sourceObjectiveStatus = "unverified-source-field" }
quests[9154] = { id = 9154, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kapelle des hoffnungsvollen Lichts", description = "Die Geißel ist in größerer Anzahl zurückgekehrt, als wir es jemals zuvor gesehen haben. Deshalb rekrutiert die Argentumdämmerung alle Männer und Frauen, die fähig und dazu bereit sind, unsere Länder zu verteidigen.\n\nFalls Ihr unserer Sache dienen wollt, bringt dieses Dokument zum Bewahrer der Schriften bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", sourceObjective = "Bringt den Ruf zu den Waffen zum Bewahrer der Schriften in die Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr seid also gekommen, unserem Orden beizutreten?", completion = "Die Argentumdämmerung hat um Hilfe gebeten, und Ihr seid unserem Ruf gefolgt. Wir haben keine Zeit, Euch angemessen auszubilden, aber wir glauben an Eure Fähigkeiten und daran, dass Ihr gemeinsam mit uns die Geißel zurückdrängen werdet.", sourceObjectiveStatus = "unverified-source-field" }
quests[9165] = { id = 9165, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfügung des freien Geleits", description = "Ohne die Hilfe von Euch Abenteurern, hätte meine Karawane es niemals geschaft! Die Geißelsoldaten, die uns im Unterholz aufgelauert haben, wollten wohl nicht, dass wir hier in einem Stück eintreffen.\n\n<Wache Didier wischt sich den Schweiß von der Stirn.>\n\nJetzt werden wir erst einmal hier warten, bis Feldmarschall Chambers eintrifft. Er wird Eure Verfügung für freies Geleit unterzeichnen, die Ihr dann zu Einsatzkommandant Metz an der Kapelle des hoffnungsvollen Lichts bringen könnt.\n\nUnd {name}, achtet in der Gegenwart von Chambers auf Eure Worte. Er ist ein Mensch der Sorte 'Ich reiße Euch den Kopf ab und breche Euch sämtliche Knochen'... mit dem Unterschied, dass er es auch wirklich tut...", sourceObjective = "Bringt die unterschriebene Verfügung des freien Geleits zu Einsatzkommandant Metz an der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9178] = { id = 9178, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Verdichteter Gewichtsstein", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-091:\n\n120 verdichtete Gewichtssteine.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 120 verdichtete Gewichtssteine und die Handwerksverfügung für die verdichteten Gewichtssteine zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Jawohl, die werden sich für die schonungslosen Waffen der Infanterie noch als nützlich erweisen.", sourceObjectiveStatus = "unverified-source-field" }
quests[9179] = { id = 9179, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Imperiale Plattenrüstung", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-428:\n\n3 imperiale Plattenrüstungen.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 3 imperiale Plattenrüstungen und die Handwerksverfügung für die imperialen Plattenrüstungen zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9181] = { id = 9181, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Vulkanischer Hammer", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-697:\n\n3 vulkanische Hämmer.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 3 vulkanische Hämmer und die Handwerksverfügung für die vulkanischen Hämmer zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", sourceObjectiveStatus = "unverified-source-field" }
quests[9182] = { id = 9182, flavor = "source-reference", locale = "deDE", source = "MultiLanguage forever 87d8e5f4c904291c24296205df97c9bc96aa6943", sourceFlavor = "forever", sourceRevision = "87d8e5f4c904291c24296205df97c9bc96aa6943", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Handwerksverfügung - Gewaltige Thoriumstreitaxt", description = "Der Inhaber dieser Handwerksverfügung hat nach Erfüllung des Vertrags Anspruch auf eine Bezahlung in Form von frei wählbaren Insignien.\n\nVertragsnummer BS-6020:\n\n3 gewaltige Thoriumstreitäxte.\n\nWas im Vertrag angefordert wurde, muss zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern gebracht werden.\n\nIm Falle von Verzug oder Beschädigung der Ware ist der Vertrag als null und nichtig anzusehen.\n\n-Einsatzkommandant Metz, die Argentumdämmerung", sourceObjective = "Bringt 3 gewaltige Thoriumstreitäxte und die Handwerksverfügung für die gewaltigen Thoriumstreitäxte zu Rottenkommandant Stonebruiser bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern.", progress = "Ihr führt einen Auftrag aus, {class}?", completion = "Die sind nicht halb so groß, wie ich es erwartet habe. Wie auch immer, Geschäft ist Geschäft.", sourceObjectiveStatus = "unverified-source-field" }
